func (m workoutMods) WithParentsCascading() WorkoutMod {
	return WorkoutModFunc(func(ctx context.Context, o *WorkoutTemplate) {
		if isDone, _ := workoutWithParentsCascadingCtx.Value(ctx); isDone {
			return
		}
		ctx = workoutWithParentsCascadingCtx.WithValue(ctx, true)
		{

			related := o.f.NewRoutineWithContext(ctx, RoutineMods.WithParentsCascading())
			m.WithRoutine(related).Apply(ctx, o)
		}
		{

			related := o.f.NewUserWithContext(ctx, UserMods.WithParentsCascading())
			m.WithUser(related).Apply(ctx, o)
		}
	})
}

